51	public class MethodNode extends NotificationAttrNode implements IMethodDetails, ILoadable, ICodeNode, Comparable<MethodNode> {
52		private static final Logger LOG = LoggerFactory.getLogger(MethodNode.class);
53		private static final InsnNode[] EMPTY_INSN_ARRAY = new InsnNode[0];
54	
55		private final MethodInfo mthInfo;
56		private final ClassNode parentClass;
57		private AccessInfo accFlags;
58	
59		private final ICodeReader codeReader;
60		private final int insnsCount;
61	
62		private boolean noCode;
63		private int regsCount;
64		private int argsStartReg;
65	
66		private boolean loaded;
67	
68		// additional info available after load, keep on unload
69		private ArgType retType;
70		private List<ArgType> argTypes;
71		private List<ArgType> typeParameters;
72	
73		// decompilation data, reset on unload
74		private RegisterArg thisArg;
75		private List<RegisterArg> argsList;
76		private @Nullable InsnNode[] instructions;
77		private List<BlockNode> blocks;
78		private int blocksMaxCId;
79		private BlockNode enterBlock;
80		private BlockNode exitBlock;

80		private BlockNode exitBlock;
81		private List<SSAVar> sVars;
82		private List<ExceptionHandler> exceptionHandlers;
83		private List<LoopInfo> loops;
84		private Region region;
85	
86		// Methods that use this method
87		private List<MethodNode> useIn = Collections.emptyList();
88		// Unresolved methods that use this method
89		private List<MethodInfo> unresolvedUsed = Collections.emptyList();
90		// Methods that this method uses
91		private Set<MethodNode> methodsUsed = new HashSet<>();
92		// True if this method contains a self call
93		private boolean callsSelf = false;
94	
95		private JavaMethod javaNode;
96	
97		public static MethodNode build(ClassNode classNode, IMethodData methodData) {
98			MethodNode methodNode = new MethodNode(classNode, methodData);
99			methodNode.addAttrs(methodData.getAttributes());
100			return methodNode;
101		}
102	
103		private MethodNode(ClassNode classNode, IMethodData mthData) {
104			this.mthInfo = MethodInfo.fromRef(classNode.root(), mthData.getMethodRef());
105			this.parentClass = classNode;
106			this.accFlags = new AccessInfo(mthData.getAccessFlags(), AFType.METHOD);
107			ICodeReader codeReader = mthData.getCodeReader();
108			if (codeReader == null) {
109				this.noCode = true;
110				this.codeReader = null;
111				this.insnsCount = 0;
112			} else {
113				this.noCode = false;
114				this.codeReader = codeReader.copy();
115				this.insnsCount = codeReader.getUnitsCount();
116			}
117	
118			this.retType = mthInfo.getReturnType();
119			this.argTypes = mthInfo.getArgumentsTypes();
120			this.typeParameters = Collections.emptyList();
121			unload();
122		}
123	
124		@Override
125		public void unload() {
126			loaded = false;
127			// don't unload retType, argTypes, typeParameters
128			thisArg = null;
129			argsList = null;
130			sVars = Collections.emptyList();
131			instructions = null;
132			blocks = null;
133			blocksMaxCId = 0;
134			enterBlock = null;
135			exitBlock = null;
136			region = null;
137			exceptionHandlers = Collections.emptyList();
138			loops = Collections.emptyList();
139			unloadAttributes();
140		}
141	
142		public void updateTypes(List<ArgType> argTypes, ArgType retType) {
143			this.argTypes = argTypes;
144			this.retType = retType;
145		}
146	
147		public void updateTypeParameters(List<ArgType> typeParameters) {
148			this.typeParameters = typeParameters;
149		}
150	
151		@Override
152		public void load() throws DecodeException {
153			if (loaded) {
154				// method already loaded
155				return;
156			}
157			try {
158				loaded = true;
159				if (noCode) {
160					regsCount = 0;
161					// TODO: registers not needed without code
162					initArguments(this.argTypes);
163					return;
164				}
165	
166				this.regsCount = codeReader.getRegistersCount();
167				this.argsStartReg = codeReader.getArgsStartReg();
168				initArguments(this.argTypes);
169	
170				if (contains(AType.JADX_ERROR)) {
