199		private void initArguments(List<ArgType> args) {
200			int pos = getArgsStartPos(args);
201			TypeUtils typeUtils = root().getTypeUtils();
202			if (accFlags.isStatic()) {
203				thisArg = null;
204			} else {
205				ArgType thisClsType = typeUtils.expandTypeVariables(this, parentClass.getType());
206				RegisterArg arg = InsnArg.reg(pos++, thisClsType);
207				arg.add(AFlag.THIS);
208				arg.add(AFlag.IMMUTABLE_TYPE);
209				thisArg = arg;
210			}
211			if (args.isEmpty()) {
212				argsList = Collections.emptyList();
213				return;
214			}
215			argsList = new ArrayList<>(args.size());
216			for (ArgType argType : args) {
217				ArgType expandedType = typeUtils.expandTypeVariables(this, argType);
218				RegisterArg regArg = InsnArg.reg(pos, expandedType);
219				regArg.add(AFlag.METHOD_ARGUMENT);
220				regArg.add(AFlag.IMMUTABLE_TYPE);
221				argsList.add(regArg);
222				pos += argType.getRegCount();
223			}
224		}
