226		private int getArgsStartPos(List<ArgType> args) {
227			if (noCode) {
228				return 0;
229			}
230			if (argsStartReg != -1) {
231				return argsStartReg;
232			}
233			int pos = regsCount;
234			for (ArgType arg : args) {
235				pos -= arg.getRegCount();
236			}
237			if (!accFlags.isStatic()) {
238				pos--;
239			}
240			return pos;
241		}
