276		public List<VarNode> collectArgNodes() {
277			ICodeInfo codeInfo = getTopParentClass().getCode();
278			int mthDefPos = getDefPosition();
279			int lineEndPos = CodeUtils.getLineEndForPos(codeInfo.getCodeStr(), mthDefPos);
280			int argsCount = mthInfo.getArgsCount();
281			List<VarNode> args = new ArrayList<>(argsCount);
282			codeInfo.getCodeMetadata().searchDown(mthDefPos, (pos, ann) -> {
283				if (pos > lineEndPos) {
284					// Stop at line end
285					return Boolean.TRUE;
286				}
287				if (ann instanceof NodeDeclareRef) {
288					ICodeNodeRef declRef = ((NodeDeclareRef) ann).getNode();
289					if (declRef instanceof VarNode) {
290						VarNode varNode = (VarNode) declRef;
291						if (!varNode.getMth().equals(this)) {
292							// Stop if we've gone too far and have entered a different method
293							return Boolean.TRUE;
294						}
295						args.add(varNode);
296					}
297				}
298				return null;
299			});
300			if (args.size() != argsCount) {
301				LOG.warn("Incorrect args count, expected: {}, got: {}", argsCount, args.size());
302			}
303			return args;
304		}
