package jadx.core.plugins;

import jadx.api.plugins.JadxPlugin;
import jadx.api.plugins.data.IJadxPlugins;
import jadx.api.plugins.data.JadxPluginRuntimeData;
import jadx.core.utils.exceptions.JadxRuntimeException;

public class JadxPluginsData implements IJadxPlugins {

	private final JadxPluginManager pluginManager;

	public JadxPluginsData(JadxPluginManager pluginManager) {
		this.pluginManager = pluginManager;
	}

	@Override
	public JadxPluginRuntimeData getById(String pluginId) {
		for (PluginRuntime p : pluginManager.getResolvedPlugins()) {
			if (p.getPluginId().equals(pluginId)) {
				return p.getPluginContext();
			}
		}
		throw new JadxRuntimeException("Plugin with id '" + pluginId + "' not found");
	}

	@Override
	public JadxPluginRuntimeData getProviding(String provideId) {
		for (PluginRuntime p : pluginManager.getResolvedPlugins()) {
			if (p.getPluginInfo().getProvides().equals(provideId)) {
				return p.getPluginContext();
			}
		}
		throw new JadxRuntimeException("Plugin providing '" + provideId + "' not found");
	}

	@SuppressWarnings("unchecked")
	@Override
	public <P extends JadxPlugin> P getInstance(Class<P> pluginCls) {
		for (PluginRuntime p : pluginManager.getResolvedPlugins()) {
			if (p.getPluginInstance().getClass().equals(pluginCls)) {
				return (P) p.getPluginInstance();
			}
		}
		throw new JadxRuntimeException("Plugin class '" + pluginCls + "' not found");
	}
}

