1	package jadx.core.dex.visitors.regions.maker;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.Objects;
6	
7	import org.jetbrains.annotations.Nullable;
8	
9	import jadx.core.dex.attributes.AFlag;
10	import jadx.core.dex.attributes.AType;
11	import jadx.core.dex.attributes.nodes.EdgeInsnAttr;
12	import jadx.core.dex.attributes.nodes.LoopInfo;
13	import jadx.core.dex.instructions.IfNode;
14	import jadx.core.dex.instructions.InsnType;
15	import jadx.core.dex.instructions.SwitchInsn;
16	import jadx.core.dex.nodes.BlockNode;
17	import jadx.core.dex.nodes.InsnContainer;
18	import jadx.core.dex.nodes.InsnNode;
19	import jadx.core.dex.nodes.MethodNode;
20	import jadx.core.dex.regions.Region;
21	import jadx.core.utils.BlockUtils;
22	import jadx.core.utils.blocks.BlockSet;
23	import jadx.core.utils.exceptions.JadxOverflowException;
24	
25	import static jadx.core.utils.BlockUtils.getNextBlock;
26	
27	public class RegionMaker {
28		private final MethodNode mth;
29		private final RegionStack stack;
30	
31		private final IfRegionMaker ifMaker;
32		private final LoopRegionMaker loopMaker;
33	
34		private final BlockSet processedBlocks;
35		private final int regionsLimit;
36	
37		private int regionsCount;
38	
39		public RegionMaker(MethodNode mth) {
40			this.mth = mth;
41			this.stack = new RegionStack(mth);
42			this.ifMaker = new IfRegionMaker(mth, this);
43			this.loopMaker = new LoopRegionMaker(mth, this, ifMaker);
44			this.processedBlocks = BlockSet.empty(mth);
45			this.regionsLimit = mth.getBasicBlocks().size() * 400;
46		}
47	
48		public Region makeMthRegion() {
49			return makeRegion(mth.getEnterBlock());
50		}
51	
52		Region makeRegion(BlockNode startBlock) {
53			Objects.requireNonNull(startBlock);
54			Region region = new Region(stack.peekRegion());
55			if (stack.containsExit(startBlock)) {
56				insertEdgeInsns(region, startBlock);
57				return region;
58			}
59			if (processedBlocks.addChecked(startBlock)) {
60				// Add block to multiple regions (duplicate the instructions in decompiled code)
61				// and allow processing to continue
62				if (!startBlock.contains(AFlag.DUPLICATED)) {
63					mth.addWarnComment("Code duplicated, block: " + startBlock + ' ' + startBlock.getAttributesString());
64					startBlock.add(AFlag.DUPLICATED);
65				}
66			}
67			BlockNode next = startBlock;
68			while (next != null) {
69				next = traverse(region, next);
70				regionsCount++;
71				if (regionsCount > regionsLimit) {
72					throw new JadxOverflowException("Regions count limit reached at block " + startBlock);
73				}
74			}
75			return region;
76		}
77	
78		/**
79		 * Recursively traverse all blocks from 'block' until block from 'exits'
80		 */
81		private @Nullable BlockNode traverse(Region r, BlockNode block) {
82			if (block.contains(AFlag.MTH_EXIT_BLOCK)) {
83				return null;
84			}
85			BlockNode next = null;
86			boolean processed = false;
87	
88			List<LoopInfo> loops = block.getAll(AType.LOOP);
89			int loopCount = loops.size();
90			if (loopCount != 0 && block.contains(AFlag.LOOP_START)) {
91				if (loopCount == 1) {
92					next = loopMaker.process(r, loops.get(0), stack);
93					processed = true;
94				} else {
95					for (LoopInfo loop : loops) {
96						if (loop.getStart() == block) {
97							next = loopMaker.process(r, loop, stack);
98							processed = true;
99							break;
100						}
101					}
102				}
103			}
104	
105			InsnNode insn = BlockUtils.getLastInsn(block);
106			if (!processed && insn != null) {
107				switch (insn.getType()) {
108					case IF:
109						next = ifMaker.process(r, block, (IfNode) insn, stack);
110						processed = true;
111						break;
112	
113					case SWITCH:
114						SwitchRegionMaker switchMaker = new SwitchRegionMaker(mth, this);
115						next = switchMaker.process(r, block, (SwitchInsn) insn, stack);
116						processed = true;
117						break;
118	
119					case MONITOR_ENTER:
120						SynchronizedRegionMaker syncMaker = new SynchronizedRegionMaker(mth, this);
121						next = syncMaker.process(r, block, insn, stack);
122						processed = true;
123						break;
124				}
125			}
126			if (!processed) {
127				r.add(block);
128				next = getNextBlock(block);
129			}
130			if (next != null && !stack.containsExit(block) && !stack.containsExit(next)) {
131				return next;
132			}
133			return null;
134		}
135	
136		private void insertEdgeInsns(Region region, BlockNode exitBlock) {
137			List<EdgeInsnAttr> edgeInsns = exitBlock.getAll(AType.EDGE_INSN);
138			if (edgeInsns.isEmpty()) {
139				return;
140			}
141			List<InsnNode> insns = new ArrayList<>(edgeInsns.size());
142			addOneInsnOfType(insns, edgeInsns, InsnType.BREAK);
143			addOneInsnOfType(insns, edgeInsns, InsnType.CONTINUE);
144			region.add(new InsnContainer(insns));
145		}
146	
147		private void addOneInsnOfType(List<InsnNode> insns, List<EdgeInsnAttr> edgeInsns, InsnType insnType) {
148			for (EdgeInsnAttr edgeInsn : edgeInsns) {
149				InsnNode insn = edgeInsn.getInsn();
150				if (insn.getType() == insnType) {
151					insns.add(insn);
152					return;
153				}
154			}
155		}
156	
157		RegionStack getStack() {
158			return stack;
159		}
160	
161		boolean isProcessed(BlockNode block) {
162			return processedBlocks.contains(block);
163		}
164	
165		void clearBlockProcessedState(BlockNode block) {
166			processedBlocks.remove(block);
167		}
168	}
