17	
18	public class TypeGen {
19		private static final Logger LOG = LoggerFactory.getLogger(TypeGen.class);
20	
21		private TypeGen() {
22		}
23	
24		public static String signature(ArgType type) {
25			PrimitiveType stype = type.getPrimitiveType();
26			if (stype == PrimitiveType.OBJECT) {
27				return Utils.makeQualifiedObjectName(type.getObject());
28			}
29			if (stype == PrimitiveType.ARRAY) {
30				return '[' + signature(type.getArrayElement());
31			}
32			return stype.getShortName();
33		}
34	
35		public static List<String> signatures(List<ArgType> types) {
36			return Utils.collectionMap(types, TypeGen::signature);
37		}
38	
39		/**
40		 * Convert literal arg to string (preferred method)
41		 */
42		public static String literalToString(LiteralArg arg, IDexNode dexNode, boolean fallback) {
43			return literalToString(arg.getLiteral(), arg.getType(),
44					dexNode.root().getStringUtils(),
45					fallback,
46					arg.contains(AFlag.EXPLICIT_PRIMITIVE_TYPE));
47		}
48	
49		/**
50		 * Convert literal value to string according to value type
51		 *
52		 * @throws JadxRuntimeException for incorrect type or literal value
53		 */
54		public static String literalToString(long lit, ArgType type, IDexNode dexNode, boolean fallback) {
55			return literalToString(lit, type, dexNode.root().getStringUtils(), fallback, false);
56		}
57	
58		public static String literalToString(long lit, ArgType type, StringUtils stringUtils, boolean fallback, boolean cast) {
59			if (type == null || !type.isTypeKnown()) {
60				String n = Long.toString(lit);
61				if (fallback && Math.abs(lit) > 100) {
62					StringBuilder sb = new StringBuilder();
63					sb.append(n).append("(0x").append(Long.toHexString(lit));
64					if (type == null || type.contains(PrimitiveType.FLOAT)) {
65						sb.append(", float:").append(Float.intBitsToFloat((int) lit));
66					}
67					if (type == null || type.contains(PrimitiveType.DOUBLE)) {
68						sb.append(", double:").append(Double.longBitsToDouble(lit));
69					}
70					sb.append(')');
71					return sb.toString();
72				}
73				return n;
74			}
75	
76			switch (type.getPrimitiveType()) {
77				case BOOLEAN:
78					return lit == 0 ? "false" : "true";
79				case CHAR:
80					return stringUtils.unescapeChar((char) lit, cast);
81				case BYTE:
82					return stringUtils.formatByte(lit, cast);
83				case SHORT:
84					return stringUtils.formatShort(lit, cast);
85				case INT:
86					return stringUtils.formatInteger(lit, cast);
87				case LONG:
88					return stringUtils.formatLong(lit, cast);
89				case FLOAT:
90					return StringUtils.formatFloat(Float.intBitsToFloat((int) lit));
91				case DOUBLE:
92					return StringUtils.formatDouble(Double.longBitsToDouble(lit));
93	
94				case OBJECT:
95				case ARRAY:
96					if (lit != 0) {
97						LOG.warn("Wrong object literal: {} for type: {}", lit, type);
98						return Long.toString(lit);
99					}
100					return "null";
101	
102				default:
103					throw new JadxRuntimeException("Unknown type in literalToString: " + type);
104			}
105		}
106	
107		@Nullable
108		public static String literalToRawString(LiteralArg arg) {
109			ArgType type = arg.getType();
110			if (type == null) {
111				return null;
112			}
113			long lit = arg.getLiteral();
114			switch (type.getPrimitiveType()) {
115				case BOOLEAN:
116					return lit == 0 ? "false" : "true";
117				case CHAR:
118					return String.valueOf((char) lit);
119	
120				case BYTE:
121				case SHORT:
122				case INT:
123				case LONG:
124					return Long.toString(lit);
125	
126				case FLOAT:
127					return Float.toString(Float.intBitsToFloat((int) lit));
128				case DOUBLE:
129					return Double.toString(Double.longBitsToDouble(lit));
130	
131				case OBJECT:
132				case ARRAY:
133					if (lit != 0) {
134						LOG.warn("Wrong object literal: {} for type: {}", lit, type);
135						return Long.toString(lit);
136					}
137					return "null";
138	
139				default:
140					return null;
141			}
142		}
143	}
