122		public void lock() {
123			try {
124				List<BlockNode> successorsList = successors;
125				successors = lockList(successorsList);
126				cleanSuccessors = successorsList == cleanSuccessors ? this.successors : lockList(cleanSuccessors);
127				predecessors = lockList(predecessors);
128				dominatesOn = lockList(dominatesOn);
129				if (domFrontier == null) {
130					throw new JadxRuntimeException("Dominance frontier not set for block: " + this);
131				}
132			} catch (Exception e) {
133				throw new JadxRuntimeException("Failed to lock block: " + this, e);
134			}
135		}
