137		/**
138		 * Return all successor which are not exception handler or followed by loop back edge
139		 */
140		private static List<BlockNode> cleanSuccessors(BlockNode block) {
141			List<BlockNode> sucList = block.getSuccessors();
142			if (sucList.isEmpty()) {
143				return sucList;
144			}
145			List<BlockNode> toRemove = new ArrayList<>(sucList.size());
146			for (BlockNode b : sucList) {
147				if (BlockUtils.isExceptionHandlerPath(b)) {
